(()=>{let nav,bank;const update=()=>{document.documentElement.style.setProperty('--station-nav-height',(nav?.getBoundingClientRect().height||0)+'px');document.documentElement.style.setProperty('--sticky-bank-height',(bank?.getBoundingClientRect().height||0)+'px');};const sizes=new ResizeObserver(update);const scan=()=>{const nextNav=document.querySelector('.station-tabs'),nextBank=document.querySelector('.word-bank');if(nextNav!==nav){if(nav)sizes.unobserve(nav);nav=nextNav;if(nav)sizes.observe(nav);}if(nextBank!==bank){if(bank)sizes.unobserve(bank);bank=nextBank;if(bank)sizes.observe(bank);}update();};new MutationObserver(scan).observe(document.body,{childList:true,subtree:true});scan();})();
